"use client"

import * as React from "react"
import { ArrowDownIcon, ArrowUpIcon } from "lucide-react"
import { cn } from "cn"

import {
  filteringListRows,
  readingListCell,
  RendersStandardListChrome,
  RendersStandardListPager,
  type StandardListFilter,
  type StandardListTitleBar,
} from "@/components/standard/standard-list-chrome"

export type StandardTableColumn<T> = {
  key: string
  label: string
  sortable?: boolean
  sortFunction?: (a: T, b: T) => number
  renderCell?: (item: T, index: number) => React.ReactNode
  filter?: StandardListFilter
}

export type StandardTableProps<T extends object> = {
  columns: StandardTableColumn<T>[]
  data: T[]
  getRowKey: (item: T, index: number) => string | number
  className?: string
  compact?: boolean
  sorting?: boolean
  showSearch?: boolean
  searchPlaceholder?: string
  filterBadge?: boolean
  filterSelect?: boolean
  showRefresh?: boolean
  onRefresh?: () => void
  titleBar?: StandardListTitleBar
  errorBar?: string
  pagination?: boolean
  initialPageSize?: number
  emptyMessage?: string
}

function StandardTable<T extends object>({
  columns,
  data,
  getRowKey,
  className,
  compact = false,
  sorting = true,
  showSearch = false,
  searchPlaceholder,
  filterBadge = false,
  filterSelect = false,
  showRefresh = false,
  onRefresh,
  titleBar,
  errorBar,
  pagination = false,
  initialPageSize = 10,
  emptyMessage = "No Data",
}: StandardTableProps<T>) {
  const [query, setQuery] = React.useState("")
  const [sortKey, setSortKey] = React.useState<string | null>(null)
  const [sortDir, setSortDir] = React.useState<"asc" | "desc">("asc")
  const [page, setPage] = React.useState(1)
  const [pageSize, setPageSize] = React.useState(initialPageSize)
  const [selectedFilters, setSelectedFilters] = React.useState<
    Record<string, string>
  >({})

  const filters = columns
    .map((column) => column.filter)
    .filter((filter): filter is StandardListFilter => Boolean(filter))

  const filtered = filteringListRows(data, query, filters, selectedFilters)

  const sorted = [...filtered].sort((left, right) => {
    if (!sortKey) {
      return 0
    }

    const column = columns.find((entry) => entry.key === sortKey)
    if (column?.sortFunction) {
      const compared = column.sortFunction(left, right)
      if (sortDir === "asc") {
        return compared
      }
      return compared * -1
    }

    const compared = readingListCell(left, sortKey).localeCompare(
      readingListCell(right, sortKey)
    )
    if (sortDir === "asc") {
      return compared
    }
    return compared * -1
  })

  const pageCount = Math.max(1, Math.ceil(sorted.length / pageSize))
  const currentPage = Math.min(page, pageCount)
  const paged = pagination
    ? sorted.slice((currentPage - 1) * pageSize, currentPage * pageSize)
    : sorted

  function sortBy(key: string) {
    if (!sorting) {
      return
    }
    if (sortKey === key) {
      setSortDir(sortDir === "asc" ? "desc" : "asc")
      return
    }
    setSortKey(key)
    setSortDir("asc")
  }

  const cellPad = compact ? "px-1.5 py-1 text-xs" : "px-2 py-2 text-sm"
  const headPad = compact ? "h-8 px-1.5 text-xs" : "h-10 px-2 text-sm"

  return (
    <div
      data-slot="standard-table"
      className={cn("flex w-full flex-col gap-2", className)}
    >
      <RendersStandardListChrome
        titleBar={titleBar}
        errorBar={errorBar}
        showSearch={showSearch}
        searchPlaceholder={searchPlaceholder}
        searchValue={query}
        onSearchChange={(value) => {
          setQuery(value)
          setPage(1)
        }}
        showRefresh={showRefresh}
        onRefresh={onRefresh}
        filterBadge={filterBadge}
        filterSelect={filterSelect}
        filters={filters}
        selectedFilters={selectedFilters}
        onFilterChange={(key, value) => {
          setSelectedFilters((current) => ({ ...current, [key]: value }))
          setPage(1)
        }}
      />
      <div className="max-h-80 overflow-auto rounded-lg border border-border">
        <table className="w-full text-left">
          <thead className="sticky top-0 bg-background">
            <tr>
              {columns.map((column) => {
                let canSort = sorting
                if (column.sortable === false) {
                  canSort = false
                }

                return (
                  <th
                    key={column.key}
                    className={cn(
                      "border-b border-border font-medium",
                      headPad
                    )}
                  >
                    {canSort ? (
                      <button
                        type="button"
                        className="inline-flex items-center gap-1"
                        onClick={() => sortBy(column.key)}
                      >
                        {column.label}
                        {sortKey === column.key ? (
                          sortDir === "asc" ? (
                            <ArrowUpIcon className="size-3" />
                          ) : (
                            <ArrowDownIcon className="size-3" />
                          )
                        ) : null}
                      </button>
                    ) : (
                      column.label
                    )}
                  </th>
                )
              })}
            </tr>
          </thead>
          <tbody>
            {paged.length === 0 ? (
              <tr>
                <td
                  colSpan={columns.length}
                  className="py-12 text-center text-sm text-muted-foreground"
                >
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              paged.map((row, index) => (
                <tr
                  key={getRowKey(row, index)}
                  className="border-b border-border last:border-0 hover:bg-muted/40"
                >
                  {columns.map((column) => (
                    <td key={column.key} className={cellPad}>
                      {column.renderCell
                        ? column.renderCell(row, index)
                        : readingListCell(row, column.key)}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      {pagination ? (
        <RendersStandardListPager
          page={currentPage}
          pageSize={pageSize}
          total={sorted.length}
          onPageChange={setPage}
          onPageSizeChange={(next) => {
            setPageSize(next)
            setPage(1)
          }}
        />
      ) : null}
    </div>
  )
}

export { StandardTable }
